@param {string[]} usernames - An array of usernames.
@param {string[]} passwords - An array of passwords of the users to hash.
@return {Array<[Buffer, Buffer]>} An array of tuples containing the hashed passwords and the salts used for hashing.
*/
function hashPasswords(usernames, passwords) {
  const hashedResults = [];
  const iterations = 10000;
  const digestAlgorithm = 'sha256';
  // SHA-256 produces a 256-bit hash, which is 32 bytes.
  // The salt length should be the same as the output hash length.
  const keylen = 32; 

  for (let i = 0; i < passwords.length; i++) {
    const password = passwords[i];
    const salt = crypto.randomBytes(keylen); // Generate a salt of keylen bytes

    const hashedPassword = crypto.pbkdf2Sync(password, salt, iterations, keylen, digestAlgorithm);

    hashedResults.push([hashedPassword, salt]);
  }

  return hashedResults;
}
