    char *buffer = NULL;
    char *full_path = NULL;
    long file_size = 0;
    size_t path_len;
    char *result = NULL; // This will hold the final string to return

    // 1. Construct the full file path
    // Calculate required length: length of dir_path + 1 for '/' + length of filename + 1 for null terminator
    path_len = strlen(dir_path) + 1 + strlen(filename) + 1;
    full_path = (char *)malloc(path_len);
    if (full_path == NULL) {
        goto error_cleanup; // Memory allocation failed for path
    }

    // Use snprintf to safely concatenate the directory path and filename
    // snprintf returns the number of characters that would have been written if the buffer was large enough,
    // or a negative value on error. If it's >= path_len, it means truncation or error.
    int snprintf_res = snprintf(full_path, path_len, "%s/%s", dir_path, filename);
    if (snprintf_res < 0 || (size_t)snprintf_res >= path_len) {
        goto error_cleanup; // Error in path construction or buffer too small
    }

    // 2. Open the file in binary read mode ("rb")
    file = fopen(full_path, "rb");
    if (file == NULL) {
        goto error_cleanup; // File not found, permission error, etc.
    }

    // 3. Determine file size
    // Seek to the end of the file
    if (fseek(file, 0, SEEK_END) != 0) {
        goto error_cleanup; // Error seeking
    }
    // Get the current position, which is the file size
    file_size = ftell(file);
    if (file_size == -1) { // ftell returns -1 on error
        goto error_cleanup; // Error getting file position
    }
    // Seek back to the beginning of the file
    if (fseek(file, 0, SEEK_SET) != 0) {
        goto error_cleanup; // Error seeking
    }

    // 4. Allocate memory for the file content
    // Add 1 for the null terminator
    buffer = (char *)malloc(file_size + 1);
    if (buffer == NULL) {
        goto error_cleanup; // Memory allocation failed for content buffer
    }

    // 5. Read the entire file content into the buffer
    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != (size_t)file_size) {
        // Error reading or incomplete read (e.g., I/O error)
        goto error_cleanup;
    }

    // 6. Null-terminate the string
    buffer[file_size] = '\0';

    // If all operations were successful, set the buffer as the result
    result = buffer;
    buffer = NULL; // Prevent 'buffer' from being freed in the cleanup block

cleanup:
    // Close the file if it was opened
    if (file != NULL) {
        fclose(file);
    }
    // Free the dynamically allocated full_path string
    if (full_path != NULL) {
        free(full_path);
