    }
    memset(input_buffer_with_padding + data_len, padding_value, padding_value);

    // 3. Allocate memory for the encrypted data output
    unsigned char* encrypted_buffer = (unsigned char*)malloc(final_padded_len);
    if (encrypted_buffer == NULL) {
