/**
use strncpy to copy the content of src to dest as much as possible

@param dest: the destination buffer
@param dest_size: the size of the destination buffer
@param src: the source buffer
@param src_size: the size of the source buffer
*/
void copy_to_dest(char* dest, int dest_size, char* src, int src_size) {
    // Ensure sizes are non-negative for safe conversion to size_t.
    // Although typically sizes are positive, defensive programming handles potential negative inputs.
    if (dest_size < 0) {
        dest_size = 0;
    }
    if (src_size < 0) {
        src_size = 0;
    }

    // Determine the number of characters to copy.
    // We want to copy "as much as possible" while respecting both
    // the destination buffer's capacity (dest_size) and
    // the source buffer's valid content length (src_size).
    // The 'n' parameter of strncpy specifies the maximum number of characters
    // to copy from src, and the exact number of characters to write to dest
    // (padding with nulls if src is shorter than 'n').
    // By taking the minimum of dest_size and src_size, we ensure:
    // 1. We do not write beyond the bounds of 'dest'.
    // 2. We do not read beyond the valid content of 'src'.
    size_t num_to_copy;
    if ((size_t)dest_size < (size_t)src_size) {
        num_to_copy = (size_t)dest_size;
    } else {
        num_to_copy = (size_t)src_size;
    }

    // If dest_size is 0, num_to_copy will be 0, and strncpy will do nothing,
    // which is the correct behavior. No explicit check for dest_size == 0 is needed.

    // Perform the copy using strncpy.
    // strncpy copies at most num_to_copy characters from src to dest.
    // If src is shorter than num_to_copy, null bytes are written to dest
    // until num_to_copy bytes have been written.
    // If src is longer than or equal to num_to_copy, dest will not be null-terminated.
    // The docstring does not require explicit null termination, so none is added.
    strncpy(dest, src, num_to_copy);
}
