@param values: the array of values
@param begin_index: the index to start resetting values
@param count: the number of values to reset
*/
void set_values_in_arr(long long* values, int begin_index, int count) {
    // Calculate the starting memory address for the reset operation.
    // This is 'values' (the base address of the array) plus 'begin_index'
    // multiplied by the size of each element (long long).
    // The pointer arithmetic `values + begin_index` correctly calculates this address.
    long long* start_ptr = values + begin_index;

    // Calculate the total number of bytes to reset.
    // Each element is a 'long long', so it occupies sizeof(long long) bytes.
    // We need to reset 'count' number of such elements.
    size_t bytes_to_reset = (size_t)count * sizeof(long long);

    // Use memset to fill the specified memory region with zeros.
    // The first argument is the starting address of the memory block.
    // The second argument is the value to set (0 for resetting to zero).
    // The third argument is the number of bytes to set.
    memset(start_ptr, 0, bytes_to_reset);
