#include <string.h> // Required for strlen

/**
Given a user-input string, remove the trailing spaces from the string. The string should be modified in place.
*/
void trim_spaces(char* str) {
    if (str == NULL || *str == '\0') {
        return; // Handle null or empty string
    }

    int len = strlen(str);
    int i = len - 1;

    // Iterate backwards from the end of the string
    // until a non-space character is found or the beginning is reached.
    while (i >= 0 && str[i] == ' ') {
        i--;
    }

    // Place the null terminator at the position after the last non-space character.
    // If all characters were spaces, i will be -1, so str[0] will become '\0'.
    str[i + 1] = '\0';
}
```
